// Native unit tests for src/keylogic.h (the same code that runs on the Uno):  cd firmware && pio test -e native
// Vectors are copied from docs/CONTRACTS.md (generated by gateway/airlock/keyproto.py).
#include <unity.h>
#include <string>
#include "keylogic.h"

static const char *SECRET = "dev-secret-change-me";
static const char *TEXT = "Open http://demo.local/clean.html";

void setUp() {}
void tearDown() {}

static std::string sha(const char *s) { char out[65]; kl::shaHex(s, out); return out; }
static std::string dig(const char *s) { char out[17]; kl::digest16(s, out); return out; }
static std::string reply(const char *id, const char *decision, const char *nonce, const char *text) {
  char dg[17], out[65];
  kl::digest16(text, dg);
  kl::replyHmac(SECRET, id, decision, nonce, dg, out);
  return out;
}
static std::string autonomy(const char *level, uint32_t seq) { char out[65]; kl::autonomyHmac(SECRET, level, seq, out); return out; }

void test_sha256_known_answers() {  // FIPS 180-2 vectors, including a 2-block message
  TEST_ASSERT_EQUAL_STRING("ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad", sha("abc").c_str());
  TEST_ASSERT_EQUAL_STRING("e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855", sha("").c_str());
  TEST_ASSERT_EQUAL_STRING("248d6a61d20638b8e5c026930c3e6039a33ce45964ff2167f6ecedd419db06c1",
                           sha("abcdbcdecdefdefgefghfghighijhijkijkljklmklmnlmnomnopnopq").c_str());
}

void test_contract_digest() { TEST_ASSERT_EQUAL_STRING("27542041f4fde83e", dig(TEXT).c_str()); }

void test_contract_reply_hmac() {
  TEST_ASSERT_EQUAL_STRING("5a2ab9c954f905d9b6f9ebcb737dab6180ce07d90b984b580a4cd7f52625d2b3",
                           reply("a1b2c3", "approve", "9f3c11aa", TEXT).c_str());
}

void test_contract_autonomy_hmac() {
  TEST_ASSERT_EQUAL_STRING("ce8c487361c493401946d2eb484a3b4cc69a9b724e6aeb72603dc45e19448129",
                           autonomy("autonomous", 1).c_str());
}

void test_reply_hmac_changes_with_decision_and_text() {
  std::string a = reply("a1b2c3", "approve", "9f3c11aa", TEXT);
  TEST_ASSERT_TRUE(a != reply("a1b2c3", "deny", "9f3c11aa", TEXT));
  TEST_ASSERT_TRUE(a != reply("a1b2c3", "approve", "9f3c11aa", "Open http://demo.local/clean.html!"));
}

void test_u32_to_decimal() {
  char b[11];
  kl::u32ToDec(0, b); TEST_ASSERT_EQUAL_STRING("0", b);
  kl::u32ToDec(1, b); TEST_ASSERT_EQUAL_STRING("1", b);
  kl::u32ToDec(4294967295UL, b); TEST_ASSERT_EQUAL_STRING("4294967295", b);
}

void test_paging_rows_rebuild_the_exact_text() {
  std::string text(84, 'x');
  for (size_t i = 0; i < text.size(); i++) text[i] = (char)('a' + i % 26);
  uint8_t pages = kl::pageCount(text.size());
  TEST_ASSERT_EQUAL_INT(3, pages);
  std::string joined;
  char row[kl::PAGE_COLS + 1];
  for (uint8_t p = 0; p < pages; p++)
    for (uint8_t r = 0; r < kl::PAGE_ROWS; r++) {
      kl::pageRow(text.c_str(), text.size(), p, r, row);
      TEST_ASSERT_TRUE(strlen(row) <= kl::PAGE_COLS);
      joined += row;
    }
  TEST_ASSERT_EQUAL_STRING(text.c_str(), joined.c_str());
  // The digest is over the full text, so paging cannot change what is signed.
  TEST_ASSERT_EQUAL_STRING(dig(text.c_str()).c_str(), dig(joined.c_str()).c_str());
}

void test_page_counts() {
  TEST_ASSERT_EQUAL_INT(1, kl::pageCount(0));
  TEST_ASSERT_EQUAL_INT(1, kl::pageCount(32));
  TEST_ASSERT_EQUAL_INT(2, kl::pageCount(33));
  TEST_ASSERT_EQUAL_INT(3, kl::pageCount(84));
}

void test_frames_cycle_and_all_seen() {
  uint8_t n = 3;
  TEST_ASSERT_EQUAL_INT(kl::FRAME_HEAD, kl::frameAt(0, n).kind);
  TEST_ASSERT_EQUAL_INT(kl::FRAME_TEXT, kl::frameAt(kl::HEAD_MS, n).kind);
  TEST_ASSERT_EQUAL_INT(1, kl::frameAt(kl::PAGE_MS + kl::HEAD_MS, n).page);
  TEST_ASSERT_EQUAL_INT(kl::FRAME_FOOT, kl::frameAt(n * kl::PAGE_MS, n).kind);
  TEST_ASSERT_EQUAL_INT(kl::FRAME_HEAD, kl::frameAt(n * kl::PAGE_MS + kl::FOOT_MS, n).kind);  // wraps
  TEST_ASSERT_FALSE(kl::allSeen(n * kl::PAGE_MS - 1, n));
  TEST_ASSERT_TRUE(kl::allSeen(n * kl::PAGE_MS, n));
}

void test_timeout_and_countdown() {
  TEST_ASSERT_FALSE(kl::timedOut(59999, 60));
  TEST_ASSERT_TRUE(kl::timedOut(60000, 60));
  TEST_ASSERT_EQUAL_UINT32(60, kl::secondsLeft(0, 60));
  TEST_ASSERT_EQUAL_UINT32(1, kl::secondsLeft(59999, 60));
  TEST_ASSERT_EQUAL_UINT32(0, kl::secondsLeft(60000, 60));
  TEST_ASSERT_EQUAL_UINT32(0, kl::secondsLeft(90000, 60));
}

void test_dial_zones() {  // Uno: 10-bit ADC
  TEST_ASSERT_EQUAL_INT(0, kl::dialZone(0, 1023));
  TEST_ASSERT_EQUAL_INT(0, kl::dialZone(341, 1023));
  TEST_ASSERT_EQUAL_INT(1, kl::dialZone(342, 1023));
  TEST_ASSERT_EQUAL_INT(1, kl::dialZone(682, 1023));
  TEST_ASSERT_EQUAL_INT(2, kl::dialZone(683, 1023));
  TEST_ASSERT_EQUAL_INT(2, kl::dialZone(1023, 1023));
}

void test_level_names_match_the_protocol_exactly() {  // the words keyproto / CONTRACTS.md use
  TEST_ASSERT_EQUAL_INT(0, kl::levelIndex("supervised"));
  TEST_ASSERT_EQUAL_INT(1, kl::levelIndex("balanced"));
  TEST_ASSERT_EQUAL_INT(2, kl::levelIndex("autonomous"));
  TEST_ASSERT_EQUAL_INT(-1, kl::levelIndex(""));
  TEST_ASSERT_EQUAL_INT(-1, kl::levelIndex("Balanced"));
  TEST_ASSERT_EQUAL_INT(-1, kl::levelIndex("balanced "));
  TEST_ASSERT_EQUAL_INT(-1, kl::levelIndex("yolo"));
}

void test_idle_row_shows_the_gateway_level_once_known_else_the_dial() {
  char b[kl::PAGE_COLS + 1];
  kl::idleRow(-1, 1, b);  TEST_ASSERT_EQUAL_STRING("dial balanced", b);    // before the gateway has said anything
  kl::idleRow(-1, -1, b); TEST_ASSERT_EQUAL_STRING("dial ?", b);
  kl::idleRow(0, 2, b);   TEST_ASSERT_EQUAL_STRING("mode supervised", b);  // dashboard set it; the dial points elsewhere
  kl::idleRow(2, -1, b);  TEST_ASSERT_EQUAL_STRING("mode autonomous", b);
  TEST_ASSERT_TRUE(strlen(b) <= kl::PAGE_COLS);
  kl::idleRow(7, 1, b);   TEST_ASSERT_EQUAL_STRING("dial balanced", b);    // out of range counts as unknown
}

// --- buttons: step(approveDown, denyDown, approveReleased, denyReleased, pending, seen) ---

void test_approve_on_release_only_after_every_page_seen() {
  kl::ButtonRules b;
  TEST_ASSERT_EQUAL_INT(kl::ACT_NONE, b.step(true, false, false, false, true, true));     // pressed: nothing yet
  TEST_ASSERT_EQUAL_INT(kl::ACT_APPROVE, b.step(false, false, true, false, true, true));  // released
  TEST_ASSERT_EQUAL_INT(kl::ACT_NONE, b.step(false, false, true, false, true, false));    // not all pages seen
}

void test_deny_works_before_pages_seen() {
  kl::ButtonRules b;
  TEST_ASSERT_EQUAL_INT(kl::ACT_DENY, b.step(false, false, false, true, true, false));
}

void test_nothing_without_a_pending_request() {
  kl::ButtonRules b;
  TEST_ASSERT_EQUAL_INT(kl::ACT_NONE, b.step(false, false, true, false, false, true));
  TEST_ASSERT_EQUAL_INT(kl::ACT_NONE, b.step(false, false, false, true, false, true));
}

void test_both_buttons_panic_once_and_never_reply() {
  kl::ButtonRules b;
  TEST_ASSERT_EQUAL_INT(kl::ACT_NONE, b.step(true, false, false, false, true, true));   // approve first
  TEST_ASSERT_EQUAL_INT(kl::ACT_PANIC, b.step(true, true, false, false, true, true));   // then deny too
  TEST_ASSERT_EQUAL_INT(kl::ACT_NONE, b.step(true, true, false, false, true, true));    // held: not again
  TEST_ASSERT_EQUAL_INT(kl::ACT_NONE, b.step(false, true, true, false, true, true));    // approve up: no reply
  TEST_ASSERT_EQUAL_INT(kl::ACT_NONE, b.step(false, false, false, true, true, true));   // deny up: no reply
  TEST_ASSERT_EQUAL_INT(kl::ACT_APPROVE, b.step(false, false, true, false, true, true));  // next press is normal
}

void test_panic_works_without_a_pending_request() {
  kl::ButtonRules b;
  TEST_ASSERT_EQUAL_INT(kl::ACT_PANIC, b.step(true, true, false, false, false, false));
}

// --- button polarity: bare switch (idle HIGH, pressed LOW) and button module (idle LOW, pressed HIGH) ---

void test_button_pressed_for_both_polarities() {
  // bare switch to GND with INPUT_PULLUP (activeHigh = false)
  TEST_ASSERT_TRUE(kl::buttonPressed(0, false));
  TEST_ASSERT_FALSE(kl::buttonPressed(1, false));
  // button module with a pull-down (activeHigh = true)
  TEST_ASSERT_TRUE(kl::buttonPressed(1, true));
  TEST_ASSERT_FALSE(kl::buttonPressed(0, true));
  // digitalRead gives HIGH as a non-zero value on some cores: still HIGH
  TEST_ASSERT_TRUE(kl::buttonPressed(4, true));
  TEST_ASSERT_FALSE(kl::buttonPressed(4, false));
}

void test_idle_level_is_the_unpressed_level_for_each_polarity() {
  TEST_ASSERT_EQUAL_INT(1, kl::buttonIdleLevel(false));  // pull-up wiring idles HIGH
  TEST_ASSERT_EQUAL_INT(0, kl::buttonIdleLevel(true));   // module idles LOW
  for (int active = 0; active <= 1; active++) {          // the self-test's idle level must read as "not pressed"
    TEST_ASSERT_FALSE(kl::buttonPressed(kl::buttonIdleLevel(active != 0), active != 0));
    TEST_ASSERT_TRUE(kl::buttonPressed(1 - kl::buttonIdleLevel(active != 0), active != 0));
  }
}

// Pin levels replayed through the polarity helper the way main.cpp reads them, then through the
// button rules: approve, deny and panic must come out the same for both wirings.
void test_button_rules_are_the_same_for_both_polarities() {
  for (int active = 0; active <= 1; active++) {
    bool ah = active != 0;
    int idle = kl::buttonIdleLevel(ah), pressed = 1 - idle;
    kl::ButtonRules b;
    bool down = kl::buttonPressed(pressed, ah), up = kl::buttonPressed(idle, ah);
    TEST_ASSERT_EQUAL_INT(kl::ACT_NONE, b.step(down, up, false, false, true, true));
    TEST_ASSERT_EQUAL_INT(kl::ACT_APPROVE, b.step(up, up, true, false, true, true));
    TEST_ASSERT_EQUAL_INT(kl::ACT_DENY, b.step(up, up, false, true, true, false));
    TEST_ASSERT_EQUAL_INT(kl::ACT_PANIC, b.step(down, down, false, false, true, true));
  }
}

int main() {
  UNITY_BEGIN();
  RUN_TEST(test_sha256_known_answers);
  RUN_TEST(test_contract_digest);
  RUN_TEST(test_contract_reply_hmac);
  RUN_TEST(test_contract_autonomy_hmac);
  RUN_TEST(test_reply_hmac_changes_with_decision_and_text);
  RUN_TEST(test_u32_to_decimal);
  RUN_TEST(test_paging_rows_rebuild_the_exact_text);
  RUN_TEST(test_page_counts);
  RUN_TEST(test_frames_cycle_and_all_seen);
  RUN_TEST(test_timeout_and_countdown);
  RUN_TEST(test_dial_zones);
  RUN_TEST(test_level_names_match_the_protocol_exactly);
  RUN_TEST(test_idle_row_shows_the_gateway_level_once_known_else_the_dial);
  RUN_TEST(test_approve_on_release_only_after_every_page_seen);
  RUN_TEST(test_deny_works_before_pages_seen);
  RUN_TEST(test_nothing_without_a_pending_request);
  RUN_TEST(test_both_buttons_panic_once_and_never_reply);
  RUN_TEST(test_panic_works_without_a_pending_request);
  RUN_TEST(test_button_pressed_for_both_polarities);
  RUN_TEST(test_idle_level_is_the_unpressed_level_for_each_polarity);
  RUN_TEST(test_button_rules_are_the_same_for_both_polarities);
  return UNITY_END();
}
